import pandas as pd
import numpy as np


class DecisionTree:
    def __init__(self, max_depth=5):
        self.max_depth = max_depth
        self.tree = None

    def entropy(self, y):
        _, counts = np.unique(y, return_counts=True)
        probs = counts / len(y)
        return -np.sum(probs * np.log2(probs + 1e-10))

    def information_gain(self, X, y, feature_idx, threshold):
        parent_entropy = self.entropy(y)

        left_mask = X[:, feature_idx] <= threshold
        right_mask = ~left_mask

        if np.sum(left_mask) == 0 or np.sum(right_mask) == 0:
            return 0

        left_entropy = self.entropy(y[left_mask])
        right_entropy = self.entropy(y[right_mask])

        n = len(y)
        child_entropy = (np.sum(left_mask) / n) * left_entropy + (np.sum(right_mask) / n) * right_entropy

        return parent_entropy - child_entropy

    def best_split(self, X, y):
        best_gain = -1
        best_feature = None
        best_threshold = None

        n_features = X.shape[1]

        for feature_idx in range(n_features):
            thresholds = np.unique(X[:, feature_idx])
            for threshold in thresholds:
                gain = self.information_gain(X, y, feature_idx, threshold)
                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold

    def build_tree(self, X, y, depth=0):
        n_samples, n_features = X.shape
        n_classes = len(np.unique(y))

        # Stopping criteria
        if depth >= self.max_depth or n_classes == 1 or n_samples < 2:
            return np.bincount(y).argmax()

        feature_idx, threshold = self.best_split(X, y)

        if feature_idx is None:
            return np.bincount(y).argmax()

        left_mask = X[:, feature_idx] <= threshold
        right_mask = ~left_mask

        if np.sum(left_mask) == 0 or np.sum(right_mask) == 0:
            return np.bincount(y).argmax()

        return {
            'feature_idx': feature_idx,
            'threshold': threshold,
            'left': self.build_tree(X[left_mask], y[left_mask], depth + 1),
            'right': self.build_tree(X[right_mask], y[right_mask], depth + 1)
        }

    def fit(self, X, y):
        self.tree = self.build_tree(X, y)

    def predict_one(self, x, node):
        if isinstance(node, (int, np.integer)):
            return node

        if x[node['feature_idx']] <= node['threshold']:
            return self.predict_one(x, node['left'])
        else:
            return self.predict_one(x, node['right'])

    def predict(self, X):
        return np.array([self.predict_one(x, self.tree) for x in X])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Decision Tree classifier."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c.startswith('x')]

    X_train = train[feature_cols].values
    y_train = train['target'].values
    X_test = test[feature_cols].values

    # Train decision tree
    tree = DecisionTree(max_depth=5)
    tree.fit(X_train, y_train)

    # Make predictions
    y_pred = tree.predict(X_test)

    predictions = pd.DataFrame({"prediction": y_pred})
    predictions.to_csv(output_csv, index=False)
